-- APPLIED 2026-10-31 to production (QA-375). Was: PREPARED -- NOT APPLIED.
--
-- Websites and phone numbers for Dutch restaurants and MICHELIN Key hotels,
-- written 2026-10-31. Generated by build_prepared.py from
-- nl_contacts_research.csv; edit that script, not this file.
--
-- Input: read-only production export (2026-10-31, _source/) of every NL
-- restaurant and hotel with an empty website_url or phone. Only empty fields
-- were researched; existing values were not re-checked (recently added).
-- Every value here is `confirmed` in nl_contacts_research.csv, read from the
-- venue's own site (source_url per row). Values left blank on purpose are
-- in the CSV as `unclear` -- see README.md.
--
--   restaurants.website_url  93
--   restaurants.phone        8
--   hotels.phone             17
--
-- Guards, one transaction: aborts if any code does not exist, is not a
-- Dutch row, or already has a value in the field (production changed since
-- the export). Updates only fields that are still empty -- never overwrites.

begin;

create temp table _nl_rest_web (code text primary key, val text not null) on commit drop;

create temp table _nl_rest_phone (code text primary key, val text not null) on commit drop;

create temp table _nl_hotel_phone (code text primary key, val text not null) on commit drop;

do $$
declare
  bad text;
begin
  select string_agg(s.code, ', ') into bad
    from _nl_rest_web s left join restaurants r on r.restaurant_code = s.code
   where r.id is null or r.country_code <> 'NL' or nullif(trim(r.website_url), '') is not null;
  if bad is not null then raise exception 'restaurants.website_url: unknown, non-NL or no longer empty: %', bad; end if;

  select string_agg(s.code, ', ') into bad
    from _nl_rest_phone s left join restaurants r on r.restaurant_code = s.code
   where r.id is null or r.country_code <> 'NL' or nullif(trim(r.phone), '') is not null;
  if bad is not null then raise exception 'restaurants.phone: unknown, non-NL or no longer empty: %', bad; end if;

  select string_agg(s.code, ', ') into bad
    from _nl_hotel_phone s left join hotels h on h.hotel_code = s.code
   where h.id is null or h.country_code <> 'NL' or nullif(trim(h.phone), '') is not null;
  if bad is not null then raise exception 'hotels.phone: unknown, non-NL or no longer empty: %', bad; end if;
end $$;

update restaurants r set website_url = s.val
  from _nl_rest_web s
 where r.restaurant_code = s.code and r.country_code = 'NL'
   and nullif(trim(r.website_url), '') is null;

update restaurants r set phone = s.val
  from _nl_rest_phone s
 where r.restaurant_code = s.code and r.country_code = 'NL'
   and nullif(trim(r.phone), '') is null;

update hotels h set phone = s.val
  from _nl_hotel_phone s
 where h.hotel_code = s.code and h.country_code = 'NL'
   and nullif(trim(h.phone), '') is null;

do $$
begin
  if (select count(*) from restaurants r join _nl_rest_web s on s.code = r.restaurant_code and r.website_url = s.val) <> 93
  or (select count(*) from restaurants r join _nl_rest_phone s on s.code = r.restaurant_code and r.phone = s.val) <> 8
  or (select count(*) from hotels h join _nl_hotel_phone s on s.code = h.hotel_code and h.phone = s.val) <> 17 then
    raise exception 'post-check failed: not every value landed';
  end if;
end $$;

commit;
